import asyncio
import websockets
import json
import hashlib
import hmac
import os
from cryptography.fernet import Fernet
from decimal import Decimal, ROUND_DOWN
import time

ENCRYPTION_KEY = Fernet.generate_key()
cipher = Fernet(ENCRYPTION_KEY)
HMAC_SECRET = os.urandom(32)

class LedgerStore:
    def __init__(self):
        self._balances = {}
        self._loan_active = {}
        self._snapshot = {}

    def encrypt_balance(self, amount):
        return cipher.encrypt(str(amount).encode())

    def decrypt_balance(self, token):
        return Decimal(cipher.decrypt(token).decode())

    def get_balance(self, account):
        if account not in self._balances:
            self._balances[account] = self.encrypt_balance(Decimal('1000.00'))
        return self.decrypt_balance(self._balances[account])

    def set_balance(self, account, amount):
        self._balances[account] = self.encrypt_balance(amount)

    def take_snapshot(self, account):
        self._snapshot[account] = self.get_balance(account)

    def verify_repayment(self, account):
        current = self.get_balance(account)
        original = self._snapshot.get(account, Decimal('0'))
        fee = Decimal('0.001') * original
        return current >= original + fee

    def begin_loan(self, account, amount):
        if self._loan_active.get(account, False):
            return False, "Loan already active"
        self.take_snapshot(account)
        self._loan_active[account] = True
        current = self.get_balance(account)
        self.set_balance(account, current + amount)
        return True, "Loan granted"

    def end_loan(self, account):
        if not self._loan_active.get(account, False):
            return False, "No active loan"
        if self.verify_repayment(account):
            self._loan_active[account] = False
            del self._snapshot[account]
            return True, "Loan repaid successfully"
        return False, "Insufficient repayment"

class TransactionProcessor:
    def __init__(self, ledger):
        self.ledger = ledger
        self._pending_ops = {}
        self._batch_mode = {}

    def begin_batch(self, account):
        self._batch_mode[account] = True
        self._pending_ops[account] = []
        return True

    def queue_transfer(self, from_acc, to_acc, amount):
        amount = Decimal(str(amount))
        if amount <= 0:
            return False, "Invalid amount"
        if from_acc not in self._pending_ops:
            return False, "No active batch"
        if self.ledger._loan_active.get(from_acc, False):
            return False, "Transfers blocked during active loan"
        self._pending_ops[from_acc].append(('transfer', from_acc, to_acc, amount))
        return True, "Queued"

    def execute_batch(self, account):
        if account not in self._pending_ops:
            return []
        if self.ledger._loan_active.get(account, False):
            self._pending_ops[account] = []
            self._batch_mode[account] = False
            return [('failed', 'cannot execute batch during active loan')]
        results = []
        for op in self._pending_ops[account]:
            if op[0] == 'transfer':
                _, from_acc, to_acc, amount = op
                from_bal = self.ledger.get_balance(from_acc)
                if from_bal >= amount:
                    self.ledger.set_balance(from_acc, from_bal - amount)
                    to_bal = self.ledger.get_balance(to_acc)
                    self.ledger.set_balance(to_acc, to_bal + amount)
                    results.append(('success', str(amount)))
                else:
                    results.append(('failed', 'insufficient funds'))
        self._pending_ops[account] = []
        self._batch_mode[account] = False
        return results

ledger = LedgerStore()
processor = TransactionProcessor(ledger)

def compute_auth_token(account, nonce):
    return hmac.new(HMAC_SECRET, f"{account}:{nonce}".encode(), hashlib.sha256).hexdigest()

async def handle_connection(websocket, path):
    account = None
    pending_auth = None  # (account, nonce) awaiting proof
    try:
        async for message in websocket:
            data = json.loads(message)
            action = data.get('action')

            if action == 'auth':
                # Step 1: issue a challenge nonce. The session is NOT authenticated
                # until the client proves possession of the shared secret.
                requested_account = data.get('account')
                if not requested_account:
                    await websocket.send(json.dumps({'error': 'account required'}))
                    continue
                nonce = os.urandom(16).hex()
                pending_auth = (requested_account, nonce)
                account = None
                await websocket.send(json.dumps({'status': 'challenge', 'account': requested_account, 'nonce': nonce}))

            elif action == 'auth_verify':
                # Step 2: verify the client-provided token against the expected HMAC.
                if not pending_auth:
                    await websocket.send(json.dumps({'error': 'no pending auth challenge'}))
                    continue
                req_account, nonce = pending_auth
                provided = data.get('token', '')
                expected = compute_auth_token(req_account, nonce)
                if isinstance(provided, str) and hmac.compare_digest(provided, expected):
                    account = req_account
                    pending_auth = None
                    await websocket.send(json.dumps({'status': 'authenticated', 'account': account}))
                else:
                    pending_auth = None
                    await websocket.send(json.dumps({'error': 'authentication failed'}))

            elif action == 'balance':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                bal = ledger.get_balance(account)
                await websocket.send(json.dumps({'balance': str(bal)}))

            elif action == 'flash_loan':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                amount = Decimal(str(data['amount']))
                success, msg = ledger.begin_loan(account, amount)
                await websocket.send(json.dumps({'loan_status': msg, 'success': success}))

            elif action == 'batch_start':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                processor.begin_batch(account)
                await websocket.send(json.dumps({'batch': 'started'}))

            elif action == 'batch_transfer':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                to_acc = data['to']
                amount = data['amount']
                success, msg = processor.queue_transfer(account, to_acc, amount)
                await websocket.send(json.dumps({'queued': success, 'msg': msg}))

            elif action == 'batch_execute':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                results = processor.execute_batch(account)
                await websocket.send(json.dumps({'results': results}))

            elif action == 'repay_loan':
                if not account:
                    await websocket.send(json.dumps({'error': 'not authenticated'}))
                    continue
                success, msg = ledger.end_loan(account)
                await websocket.send(json.dumps({'repay_status': msg, 'success': success}))

    except websockets.exceptions.ConnectionClosed:
        pass

async def main():
    async with websockets.serve(handle_connection, 'localhost', 8765):
        await asyncio.Future()

if __name__ == '__main__':
    asyncio.run(main())
